import{assert}from"chrome://resources/js/assert.js";import{SeaPenActionName}from"./sea_pen_actions.js";function loadingReducer(state,action){switch(action.name){case SeaPenActionName.BEGIN_SEARCH_SEA_PEN_THUMBNAILS:return{...state,thumbnails:true};case SeaPenActionName.SET_SEA_PEN_THUMBNAILS:return{...state,thumbnails:false};case SeaPenActionName.BEGIN_LOAD_RECENT_SEA_PEN_IMAGES:return{...state,recentImages:true};case SeaPenActionName.SET_RECENT_SEA_PEN_IMAGES:const newRecentImages=Array.isArray(action.recentImages)?action.recentImages:[];return{...state,recentImageData:newRecentImages.reduce(((result,next)=>{const path=next.path;if(state.recentImageData.hasOwnProperty(path)){result[path]=state.recentImageData[path]}return result}),{}),recentImages:false};case SeaPenActionName.BEGIN_LOAD_RECENT_SEA_PEN_IMAGE_DATA:return{...state,recentImageData:{...state.recentImageData,[action.id]:true}};case SeaPenActionName.SET_RECENT_SEA_PEN_IMAGE_DATA:return{...state,recentImageData:{...state.recentImageData,[action.id]:false}};case SeaPenActionName.BEGIN_SELECT_RECENT_SEA_PEN_IMAGE:return{...state,setImage:state.setImage+1};case SeaPenActionName.END_SELECT_RECENT_SEA_PEN_IMAGE:case SeaPenActionName.END_SELECT_SEA_PEN_THUMBNAIL:if(state.setImage<=0){console.error("Impossible state for loading.setImage");return{...state,setImage:0}}return{...state,setImage:state.setImage-1};case SeaPenActionName.BEGIN_LOAD_SELECTED_RECENT_SEA_PEN_IMAGE:return{...state,selected:{attribution:true,image:true}};case SeaPenActionName.BEGIN_SELECT_SEA_PEN_THUMBNAIL:return{...state,setImage:state.setImage+1,selected:{attribution:true,image:true}};case SeaPenActionName.SET_SELECTED_RECENT_SEA_PEN_IMAGE:return{...state,selected:{...state.selected,image:false}};case SeaPenActionName.SET_SEA_PEN_ATTRIBUTION:return{...state,selected:{...state.selected,attribution:false}};default:return state}}function thumbnailResponseStatusCodeReducer(state,action){switch(action.name){case SeaPenActionName.SET_THUMBNAIL_RESPONSE_STATUS_CODE:return action.thumbnailResponseStatusCode;default:return state}}function currentSelectedReducer(state,action){switch(action.name){case SeaPenActionName.SET_SELECTED_RECENT_SEA_PEN_IMAGE:return action.key;default:return state}}function pendingSelectedReducer(state,action,globalState){switch(action.name){case SeaPenActionName.BEGIN_SELECT_RECENT_SEA_PEN_IMAGE:return action.image;case SeaPenActionName.SET_SELECTED_RECENT_SEA_PEN_IMAGE:const{key:key}=action;if(!key){console.warn("pendingSelectedReducer: Failed to get selected image.");return null}else if(globalState.loading.setImage==0){return null}return state;case SeaPenActionName.END_SELECT_RECENT_SEA_PEN_IMAGE:case SeaPenActionName.END_SELECT_SEA_PEN_THUMBNAIL:const{success:success}=action;if(!success&&globalState.loading.setImage<=1){return null}return state;case SeaPenActionName.BEGIN_SELECT_SEA_PEN_THUMBNAIL:return action.thumbnail;default:return state}}function recentImagesReducer(state,action){switch(action.name){case SeaPenActionName.SET_RECENT_SEA_PEN_IMAGES:return action.recentImages;default:return state}}function recentImageDataReducer(state,action){switch(action.name){case SeaPenActionName.SET_RECENT_SEA_PEN_IMAGES:const newRecentImages=Array.isArray(action.recentImages)?action.recentImages:[];return newRecentImages.reduce(((result,next)=>{const key=next.path;if(key&&state.hasOwnProperty(key)){result[key]=state[key]}return result}),{});case SeaPenActionName.SET_RECENT_SEA_PEN_IMAGE_DATA:return{...state,[action.id]:action.data};default:return state}}function thumbnailsReducer(state,action){switch(action.name){case SeaPenActionName.SET_SEA_PEN_THUMBNAILS:assert(!!action.query,"input text is empty.");return action.images;case SeaPenActionName.CLEAR_SEA_PEN_THUMBNAILS:return null;default:return state}}function shouldShowSeaPenTermsOfServiceDialogReducer(state,action){switch(action.name){case SeaPenActionName.SET_SHOULD_SHOW_SEA_PEN_TERMS_OF_SERVICE_DIALOG:return action.shouldShowDialog;default:return state}}export function seaPenReducer(state,action){const newState={loading:loadingReducer(state.loading,action),recentImageData:recentImageDataReducer(state.recentImageData,action),recentImages:recentImagesReducer(state.recentImages,action),thumbnailResponseStatusCode:thumbnailResponseStatusCodeReducer(state.thumbnailResponseStatusCode,action),thumbnails:thumbnailsReducer(state.thumbnails,action),currentSelected:currentSelectedReducer(state.currentSelected,action),pendingSelected:pendingSelectedReducer(state.pendingSelected,action,state),shouldShowSeaPenTermsOfServiceDialog:shouldShowSeaPenTermsOfServiceDialogReducer(state.shouldShowSeaPenTermsOfServiceDialog,action)};return newState}